# Chaque valeur contient, sans modification, le code source de l'ancien script.
SCRIPTS = {
    '44_collecter_variables_macro.py': '"""\nCollecte des variables macroéconomiques annuelles du Maroc, 2000-2025.\n\nLes séries quantitatives proviennent de l\'API officielle de la Banque mondiale.\nLes indicateurs de crise et de réforme sont des variables documentaires simples,\npas des mesures causales. Les valeurs indisponibles restent manquantes : aucune\nextrapolation automatique n\'est réalisée.\n"""\n\nfrom pathlib import Path\nimport json\nfrom urllib.request import urlopen\n\nimport pandas as pd\n\n\nOUT = Path("data/output")\nOUTPUT = OUT / "variables_macroeconomiques_maroc_2000_2025.xlsx"\nCOUNTRY = "MAR"\nINDICATORS = {\n    "croissance_pib_pct": "NY.GDP.MKTP.KD.ZG",\n    "inflation_ippc_pct": "FP.CPI.TOTL.ZG",\n    "chomage_pct": "SL.UEM.TOTL.ZS",\n    "ouverture_commerciale_pct_pib": "NE.TRD.GNFS.ZS",\n}\n\n\ndef world_bank_series(code):\n    """Télécharge une série et retourne un dictionnaire année-valeur."""\n    url = (\n        f"https://api.worldbank.org/v2/country/{COUNTRY}/indicator/{code}"\n        "?format=json&per_page=100"\n    )\n    with urlopen(url, timeout=60) as response:\n        payload = json.load(response)\n    if not isinstance(payload, list) or len(payload) < 2:\n        raise ValueError(f"Réponse API invalide pour {code}")\n    return {\n        int(row["date"]): row["value"]\n        for row in payload[1]\n        if row.get("date", "").isdigit()\n    }, url\n\n\ndef main():\n    years = pd.DataFrame({"annee": range(2000, 2026)})\n    sources = []\n    for variable, code in INDICATORS.items():\n        values, url = world_bank_series(code)\n        years[variable] = years["annee"].map(values)\n        sources.append({\n            "variable": variable,\n            "code_source": code,\n            "institution": "Banque mondiale",\n            "url_api": url,\n            "unite": "Pourcentage annuel",\n            "traitement": "Valeur officielle; absence conservée",\n        })\n\n    # Variables de contexte définies avant la modélisation.\n    years["crise_financiere_2008_2009"] = years["annee"].isin([2008, 2009]).astype(int)\n    years["choc_covid_2020_2021"] = years["annee"].isin([2020, 2021]).astype(int)\n    years["reforme_is_convergence_depuis_2023"] = years["annee"].ge(2023).astype(int)\n    years["tendance_temporelle"] = years["annee"] - 2000\n\n    sources.extend([\n        {\n            "variable": "crise_financiere_2008_2009",\n            "code_source": "construction",\n            "institution": "Variable de contrôle",\n            "url_api": "",\n            "unite": "0/1",\n            "traitement": "1 pour 2008-2009",\n        },\n        {\n            "variable": "choc_covid_2020_2021",\n            "code_source": "construction",\n            "institution": "Variable de contrôle",\n            "url_api": "",\n            "unite": "0/1",\n            "traitement": "1 pour 2020-2021",\n        },\n        {\n            "variable": "reforme_is_convergence_depuis_2023",\n            "code_source": "LF 2023",\n            "institution": "Ministère de l\'Économie et des Finances",\n            "url_api": "https://www.finances.gov.ma/Publication/dgi/2023/tableau-mesures-lf2023.pdf",\n            "unite": "0/1",\n            "traitement": "1 à partir de 2023; convergence progressive des taux",\n        },\n    ])\n    sources = pd.DataFrame(sources)\n    missing = pd.DataFrame([\n        {\n            "variable": column,\n            "annee_min_disponible": years.loc[years[column].notna(), "annee"].min(),\n            "annee_max_disponible": years.loc[years[column].notna(), "annee"].max(),\n            "valeurs_manquantes": int(years[column].isna().sum()),\n        }\n        for column in INDICATORS\n    ])\n    methodology = pd.DataFrame([\n        ["Période", "2000-2025"],\n        ["Fréquence", "Annuelle"],\n        ["Jointure future", "Par année de l\'information t, pas par année cible t+1"],\n        ["Taux légal IS", "Non ajouté : taux multiples selon bénéfice et secteur"],\n        ["Valeurs manquantes", "Conservées; imputation apprise dans le pipeline"],\n        ["Interprétation", "Variables de contexte, pas identification causale"],\n    ], columns=["element", "description"])\n\n    with pd.ExcelWriter(OUTPUT, engine="openpyxl") as writer:\n        years.to_excel(writer, sheet_name="Variables annuelles", index=False)\n        sources.to_excel(writer, sheet_name="Sources", index=False)\n        missing.to_excel(writer, sheet_name="Couverture", index=False)\n        methodology.to_excel(writer, sheet_name="Methodologie", index=False)\n    print(years.to_string(index=False))\n    print(f"\\nCréé : {OUTPUT}")\n\n\nif __name__ == "__main__":\n    main()\n',
    '45_tester_variables_macro.py': '"""\nTest de la valeur prédictive des variables macroéconomiques.\n\nLe modèle de base et le modèle enrichi sont comparés sur des prévisions\ntemporelles hors échantillon de 2016 à 2022. Le jeu de variables retenu sur ce\nbacktest est ensuite évalué sur 2023-2025, sans sélection fondée sur le test.\n"""\n\nfrom importlib.util import module_from_spec, spec_from_file_location\nfrom pathlib import Path\n\nimport numpy as np\nimport pandas as pd\n\n\nOUT = Path("data/output")\nINPUT = OUT / "prevision_is_t_plus_1.csv"\nMACRO = OUT / "variables_macroeconomiques_maroc_2000_2025.xlsx"\nOUTPUT = OUT / "test_variables_macroeconomiques_is.xlsx"\nPREDICTIONS = OUT / "predictions_test_avec_macro.csv"\nTARGET = "is_cible_t_plus_1"\nDELTA = "delta_is_cible"\nMACRO_VARIABLES = [\n    "croissance_pib_pct",\n    "inflation_ippc_pct",\n    "chomage_pct",\n    "ouverture_commerciale_pct_pib",\n    "crise_financiere_2008_2009",\n    "choc_covid_2020_2021",\n    "reforme_is_convergence_depuis_2023",\n]\nPARAMS = {\n    "n_estimators": 100,\n    "learning_rate": 0.03,\n    "max_depth": 1,\n    "min_samples_leaf": 10,\n}\n\nspec = spec_from_file_location("delta_module", Path("37_analyse_erreurs_et_delta_is.py"))\ndelta_module = module_from_spec(spec)\nspec.loader.exec_module(delta_module)\n\n\ndef model(numeric, categorical):\n    return delta_module.make_model(\n        "GradientBoosting_delta", numeric, categorical, PARAMS\n    )\n\n\ndef rolling_predictions(data, years, numeric, categorical, label):\n    """Produit les prévisions d\'un jeu de variables sur plusieurs années."""\n    features = numeric + categorical\n    rows = []\n    for year in years:\n        train = data[data["annee_cible"].lt(year)]\n        evaluation = data[data["annee_cible"].eq(year)].copy()\n        if len(train) < 50 or evaluation.empty:\n            continue\n        fitted = model(numeric, categorical)\n        fitted.fit(train[features], train[DELTA])\n        evaluation["delta_predit"] = fitted.predict(evaluation[features])\n        evaluation["prediction"] = np.maximum(\n            evaluation["is_mad"] + evaluation["delta_predit"], 0\n        )\n        evaluation["jeu_variables"] = label\n        rows.append(evaluation)\n    return pd.concat(rows, ignore_index=True)\n\n\ndef summarize(frame, period):\n    rows = []\n    for label, group in frame.groupby("jeu_variables"):\n        rows.append({\n            "periode": period,\n            "jeu_variables": label,\n            "observations": len(group),\n            **delta_module.score_level(group[TARGET], group["prediction"]),\n        })\n    return pd.DataFrame(rows)\n\n\ndef main():\n    data = pd.read_csv(INPUT).dropna(subset=[TARGET, "is_mad"]).copy()\n    macro = pd.read_excel(MACRO, sheet_name="Variables annuelles")\n    # Jointure sur l\'année t : les variables doivent être connues au moment de\n    # produire la prévision t+1.\n    data = data.merge(macro, on="annee", how="left", validate="many_to_one")\n    data["est_banque"] = data["est_banque"].astype(str)\n    data[DELTA] = data[TARGET] - data["is_mad"]\n    categorical = [x for x in delta_module.CATEGORICAL if x in data.columns]\n    base_numeric = [x for x in delta_module.NUMERIC if x in data.columns]\n    macro_numeric = base_numeric + MACRO_VARIABLES\n\n    historical_frames = [\n        rolling_predictions(\n            data, range(2016, 2023), base_numeric, categorical, "Base V16"\n        ),\n        rolling_predictions(\n            data, range(2016, 2023), macro_numeric, categorical, "Base + macro"\n        ),\n    ]\n    historical = pd.concat(historical_frames, ignore_index=True)\n    backtest = summarize(historical, "2016-2022").sort_values("MAE_MAD")\n    selected_label = backtest.iloc[0]["jeu_variables"]\n    selected_numeric = (\n        macro_numeric if selected_label == "Base + macro" else base_numeric\n    )\n\n    train = data[data["annee_cible"].le(2022)]\n    test = data[data["annee_cible"].ge(2023)].copy()\n    test_frames = []\n    for label, numeric in [\n        ("Base V16", base_numeric),\n        ("Base + macro", macro_numeric),\n    ]:\n        features = numeric + categorical\n        fitted = model(numeric, categorical)\n        fitted.fit(train[features], train[DELTA])\n        current = test.copy()\n        current["delta_predit"] = fitted.predict(current[features])\n        current["prediction"] = np.maximum(\n            current["is_mad"] + current["delta_predit"], 0\n        )\n        current["jeu_variables"] = label\n        test_frames.append(current)\n    test_predictions = pd.concat(test_frames, ignore_index=True)\n    test_results = summarize(test_predictions, "2023-2025").sort_values("MAE_MAD")\n\n    annual_rows = []\n    for (label, year), group in historical.groupby(\n        ["jeu_variables", "annee_cible"]\n    ):\n        annual_rows.append({\n            "jeu_variables": label,\n            "annee_cible": year,\n            "observations": len(group),\n            **delta_module.score_level(group[TARGET], group["prediction"]),\n        })\n    annual = pd.DataFrame(annual_rows)\n\n    controls = pd.DataFrame([\n        ["Jointure macro", "Année des variables t", "Pas de fuite t+1"],\n        ["Période sélection", "2016-2022", "Avant test"],\n        ["Jeu retenu historiquement", selected_label, "Selon MAE"],\n        ["Période test", "2023-2025", "Non utilisée pour sélectionner"],\n        ["Actualisation prévision 2026",\n         "Seulement si macro retenu historiquement", "Règle définie"],\n    ], columns=["controle", "valeur", "statut"])\n\n    test_predictions.to_csv(PREDICTIONS, index=False, encoding="utf-8-sig")\n    with pd.ExcelWriter(OUTPUT, engine="openpyxl") as writer:\n        backtest.to_excel(writer, sheet_name="Backtest agrege", index=False)\n        annual.to_excel(writer, sheet_name="Backtest annuel", index=False)\n        test_results.to_excel(writer, sheet_name="Comparaison test", index=False)\n        historical.to_excel(writer, sheet_name="Predictions historiques", index=False)\n        controls.to_excel(writer, sheet_name="Controles", index=False)\n\n    print("Backtest de sélection 2016-2022 :")\n    print(backtest.to_string(index=False))\n    print("\\nJeu retenu :", selected_label)\n    print("\\nComparaison informative 2023-2025 :")\n    print(test_results.to_string(index=False))\n    print(f"\\nCréé : {OUTPUT}")\n    print(f"Créé : {PREDICTIONS}")\n\n\nif __name__ == "__main__":\n    main()\n',
    '46_extraire_variables_bancaires.py': '"""\nExtraction ciblée du PNB et du coût du risque dans les rapports bancaires.\n\nCette étape produit des candidats auditables, sans modifier la base V16. Chaque\nvaleur conserve le rapport, la page, le contexte, l\'unité et le périmètre\ndétecté. Une validation distincte sera requise avant intégration au modèle.\n"""\n\nfrom pathlib import Path\nimport re\nimport unicodedata\n\nimport fitz\nimport pandas as pd\n\n\nOUT = Path("data/output")\nPANEL = OUT / "diagnostic_panel_is_financier.xlsx"\nFINANCIAL = OUT / "variables_financieres_base_prevalidee_v16.xlsx"\nOUTPUT = OUT / "candidats_variables_bancaires.xlsx"\n\nNUMBER = re.compile(r"\\(?-?\\d[\\d \\u00a0\\u202f.]*(?:,\\d+)?\\)?")\nILLEGAL_EXCEL = re.compile(r"[\\x00-\\x08\\x0b\\x0c\\x0e-\\x1f]")\nLABELS = {\n    "produit_net_bancaire": [\n        "produit net bancaire",\n        "pnb",\n    ],\n    "cout_du_risque": [\n        "cout du risque",\n        "coût du risque",\n        "cout net du risque",\n        "coût net du risque",\n    ],\n}\n\n\ndef normalize(text):\n    """Normalise les accents et espaces pour rechercher les libellés."""\n    value = unicodedata.normalize("NFKD", str(text))\n    value = "".join(c for c in value if not unicodedata.combining(c))\n    return re.sub(r"\\s+", " ", value.lower()).strip()\n\n\ndef parse_number(raw):\n    """Convertit les formats français, espaces fins et parenthèses négatives."""\n    text = str(raw).strip().replace("\\u202f", " ").replace("\\u00a0", " ")\n    negative = text.startswith("(") and text.endswith(")")\n    text = text.strip("()").replace(" ", "")\n    if "," in text:\n        text = text.replace(".", "").replace(",", ".")\n    else:\n        parts = text.split(".")\n        if len(parts) > 2 or (len(parts) == 2 and len(parts[-1]) == 3):\n            text = "".join(parts)\n    try:\n        value = float(text)\n    except ValueError:\n        return None\n    return -value if negative else value\n\n\ndef page_unit(text):\n    """Détermine le multiplicateur seulement lorsque l\'unité est explicite."""\n    value = normalize(text)\n    if re.search(r"\\b(mmad|millions? de (dh|mad|dirhams?))\\b", value):\n        return 1_000_000, "millions MAD"\n    if re.search(r"\\b(kmad|milliers? de (dh|mad|dirhams?))\\b", value):\n        return 1_000, "milliers MAD"\n    if re.search(r"\\b(en )?(dh|mad|dirhams?)\\b", value):\n        return 1, "MAD"\n    return None, "unité non détectée"\n\n\ndef page_scope(text, source):\n    """Classe le périmètre avec des marqueurs explicites du rapport."""\n    value = normalize(text)\n    social = sum(x in value for x in ["comptes sociaux", "etats sociaux"])\n    consolidated = sum(\n        x in value for x in ["comptes consolides", "compte de resultat consolide", "ifrs"]\n    )\n    if "_consolide_" in str(source).lower():\n        consolidated += 2\n    if social > consolidated:\n        return "sociaux"\n    if consolidated > social:\n        return "consolides"\n    return "a_controler"\n\n\ndef extract_pdf(source_pdf, report_year):\n    """Extrait les lignes pertinentes et tous leurs nombres candidats."""\n    path = Path(source_pdf)\n    if not path.exists():\n        return []\n    try:\n        document = fitz.open(path)\n    except Exception:\n        return []\n    rows = []\n    try:\n        for page_number, page in enumerate(document, start=1):\n            text = page.get_text("text")\n            lines = [x.strip() for x in text.splitlines() if x.strip()]\n            unit, unit_label = page_unit(text)\n            scope = page_scope(text, source_pdf)\n            for index, line in enumerate(lines):\n                normalized_line = normalize(line)\n                for variable, labels in LABELS.items():\n                    normalized_labels = [normalize(x) for x in labels]\n                    if not any(\n                        label == "pnb"\n                        and re.search(r"\\bpnb\\b", normalized_line)\n                        or label != "pnb" and label in normalized_line\n                        for label in normalized_labels\n                    ):\n                        continue\n                    context_lines = lines[max(0, index - 2):min(len(lines), index + 5)]\n                    context = " | ".join(context_lines)\n                    numbers = []\n                    for raw in NUMBER.findall(context):\n                        value = parse_number(raw)\n                        if value is None or 1900 <= abs(value) <= 2100:\n                            continue\n                        # Les pourcentages et numéros de notes sont peu plausibles.\n                        if abs(value) < 10:\n                            continue\n                        numbers.append((raw, value))\n                    for position, (raw, value) in enumerate(numbers, start=1):\n                        amount = value * unit if unit is not None else pd.NA\n                        rows.append({\n                            "variable": variable,\n                            "annee_rapport": report_year,\n                            "page_pdf": page_number,\n                            "type_page": scope,\n                            "libelle": line,\n                            "contexte": context,\n                            "position_nombre": position,\n                            "valeur_brute": raw,\n                            "valeur_numerique": value,\n                            "unite_page": unit_label,\n                            "multiplicateur": unit,\n                            "valeur_candidate_mad": amount,\n                            "source_pdf": str(source_pdf),\n                        })\n    finally:\n        document.close()\n    return rows\n\n\ndef main():\n    panel = pd.read_excel(PANEL, sheet_name="Panel provisoire")\n    banks = panel[\n        panel["secteur"].astype(str).map(normalize).str.contains("banque", na=False)\n    ][["societe", "annee", "type_comptes_resolu"]].drop_duplicates()\n    values = pd.read_excel(FINANCIAL, sheet_name=1)\n    sources = values.merge(\n        banks[["societe", "annee"]], on=["societe", "annee"], how="inner"\n    )[["societe", "annee", "annee_rapport", "source_pdf"]].dropna().drop_duplicates()\n\n    # Un PDF est analysé une fois. La correspondance société-année est restaurée\n    # ensuite à partir du catalogue des sources.\n    pdf_catalog = (\n        sources.sort_values(["source_pdf", "annee_rapport"])\n        .drop_duplicates("source_pdf")\n    )\n    extracted = []\n    for position, row in enumerate(pdf_catalog.itertuples(index=False), start=1):\n        if position == 1 or position % 20 == 0 or position == len(pdf_catalog):\n            print(f"[{position}/{len(pdf_catalog)}] {row.source_pdf}", flush=True)\n        for candidate in extract_pdf(row.source_pdf, int(row.annee_rapport)):\n            candidate["societe"] = row.societe\n            extracted.append(candidate)\n    candidates = pd.DataFrame(extracted)\n    if candidates.empty:\n        raise RuntimeError("Aucun candidat bancaire extrait")\n\n    # Le score facilite la revue, mais ne constitue pas une validation.\n    candidates["unite_explicite"] = candidates["multiplicateur"].notna()\n    candidates["score_revue"] = (\n        30 * candidates["unite_explicite"].astype(int)\n        + 20 * candidates["type_page"].ne("a_controler").astype(int)\n        + 10 * candidates["position_nombre"].le(2).astype(int)\n    )\n    candidates.sort_values(\n        ["societe", "variable", "annee_rapport", "score_revue"],\n        ascending=[True, True, True, False],\n        inplace=True,\n    )\n    # Certains PDF contiennent des caractères de contrôle invisibles refusés\n    # par Excel. Ils sont retirés sans modifier le contenu financier.\n    for column in candidates.select_dtypes(include=["object"]).columns:\n        candidates[column] = candidates[column].map(\n            lambda value: ILLEGAL_EXCEL.sub("", value)\n            if isinstance(value, str)\n            else value\n        )\n    coverage = (\n        candidates.groupby(["societe", "variable"])\n        .agg(\n            rapports=("source_pdf", "nunique"),\n            annees_rapports=("annee_rapport", "nunique"),\n            candidats=("valeur_candidate_mad", "size"),\n            candidats_avec_unite=("valeur_candidate_mad", "count"),\n        )\n        .reset_index()\n    )\n    methodology = pd.DataFrame([\n        ["Statut", "Candidats non validés"],\n        ["Variables", "Produit net bancaire; coût du risque"],\n        ["Validation requise", "Année, colonne, unité et périmètre"],\n        ["Modification V16", "Aucune"],\n        ["Règle d\'intégration", "Seulement après preuve PDF"],\n    ], columns=["element", "description"])\n\n    with pd.ExcelWriter(OUTPUT, engine="openpyxl") as writer:\n        candidates.to_excel(writer, sheet_name="Tous candidats", index=False)\n        coverage.to_excel(writer, sheet_name="Couverture candidats", index=False)\n        banks.to_excel(writer, sheet_name="Observations banques", index=False)\n        methodology.to_excel(writer, sheet_name="Methodologie", index=False)\n    print("\\nBanques :", banks["societe"].nunique())\n    print("PDF analysés :", len(pdf_catalog))\n    print("Candidats :", len(candidates))\n    print("\\nCouverture :")\n    print(coverage.to_string(index=False))\n    print(f"\\nCréé : {OUTPUT}")\n\n\nif __name__ == "__main__":\n    main()\n',
    '47_valider_variables_bancaires.py': '"""\nValidation prudente des candidats PNB et coût du risque.\n\nUne valeur est reconstruite à partir des nombres placés immédiatement après le\nlibellé. Les publications de l\'année t et les comparatifs du rapport t+1 sont\nensuite rapprochés. Une valeur n\'est déclarée validée automatiquement que si les\ndeux sources concordent à 2 % près et si le périmètre et l\'unité sont cohérents.\n"""\n\nfrom pathlib import Path\nimport re\nimport unicodedata\n\nimport numpy as np\nimport pandas as pd\n\n\nOUT = Path("data/output")\nCANDIDATES = OUT / "candidats_variables_bancaires.xlsx"\nPANEL = OUT / "diagnostic_panel_is_financier.xlsx"\nOUTPUT = OUT / "variables_bancaires_validees.xlsx"\nNUMBER_ONLY = re.compile(r"^\\s*\\(?-?\\d[\\d \\u00a0\\u202f.]*(?:,\\d+)?\\)?\\s*$")\n\n\ndef normalize(text):\n    value = unicodedata.normalize("NFKD", str(text))\n    value = "".join(c for c in value if not unicodedata.combining(c))\n    return re.sub(r"\\s+", " ", value.lower()).strip()\n\n\ndef parse_number(raw):\n    text = str(raw).strip().replace("\\u202f", " ").replace("\\u00a0", " ")\n    negative = text.startswith("(") and text.endswith(")")\n    text = text.strip("()").replace(" ", "")\n    if "," in text:\n        text = text.replace(".", "").replace(",", ".")\n    else:\n        parts = text.split(".")\n        if len(parts) > 2 or (len(parts) == 2 and len(parts[-1]) == 3):\n            text = "".join(parts)\n    try:\n        value = float(text)\n    except ValueError:\n        return None\n    return -value if negative else value\n\n\ndef values_after_label(context, variable):\n    """Retourne au maximum les deux colonnes numériques suivant le libellé."""\n    segments = [x.strip() for x in str(context).split("|")]\n    markers = (\n        ["produit net bancaire", "pnb"]\n        if variable == "produit_net_bancaire"\n        else ["cout du risque", "cout net du risque"]\n    )\n    for index, segment in enumerate(segments):\n        normalized = normalize(segment)\n        if not any(\n            marker == "pnb" and re.search(r"\\bpnb\\b", normalized)\n            or marker != "pnb" and marker in normalized\n            for marker in markers\n        ):\n            continue\n        values = []\n        # Un montant peut se trouver sur la même ligne après le libellé.\n        tail = normalized\n        for marker in markers:\n            tail = re.sub(rf"\\b{re.escape(marker)}\\b", "", tail)\n        same_line = re.findall(r"\\(?-?\\d[\\d \\u00a0\\u202f.]*(?:,\\d+)?\\)?", tail)\n        for raw in same_line:\n            value = parse_number(raw)\n            if value is not None and abs(value) >= 10:\n                values.append(value)\n        for following in segments[index + 1:]:\n            if NUMBER_ONLY.match(following):\n                value = parse_number(following)\n                if value is not None and abs(value) >= 10:\n                    values.append(value)\n                if len(values) >= 2:\n                    break\n            elif values:\n                break\n        if values:\n            return values[:2]\n    return []\n\n\ndef main():\n    candidates = pd.read_excel(CANDIDATES, sheet_name="Tous candidats")\n    occurrences = candidates.drop_duplicates(\n        ["societe", "variable", "annee_rapport", "source_pdf", "page_pdf", "contexte"]\n    ).copy()\n    reconstructed = []\n    for row in occurrences.itertuples(index=False):\n        values = values_after_label(row.contexte, row.variable)\n        if not values or pd.isna(row.multiplicateur):\n            continue\n        for offset, value in enumerate(values):\n            year = int(row.annee_rapport) - offset\n            amount = value * float(row.multiplicateur)\n            plausible = (\n                1_000_000 <= amount <= 100_000_000_000\n                if row.variable == "produit_net_bancaire"\n                else abs(amount) <= 100_000_000_000\n            )\n            if not plausible:\n                continue\n            reconstructed.append({\n                "societe": row.societe,\n                "variable": row.variable,\n                "annee": year,\n                "annee_rapport": int(row.annee_rapport),\n                "type_page": row.type_page,\n                "valeur_mad": amount,\n                "valeur_numerique": value,\n                "unite_page": row.unite_page,\n                "source_pdf": row.source_pdf,\n                "page_pdf": row.page_pdf,\n                "libelle": row.libelle,\n                "contexte": row.contexte,\n                "origine": "courant" if offset == 0 else "comparatif",\n            })\n    reconstructed = pd.DataFrame(reconstructed).drop_duplicates()\n\n    banks = pd.read_excel(PANEL, sheet_name="Panel provisoire")\n    banks = banks[\n        banks["secteur"].astype(str).map(normalize).str.contains("banque", na=False)\n    ][["societe", "annee", "type_comptes_resolu", "is_mad"]].drop_duplicates()\n    matched = reconstructed.merge(banks, on=["societe", "annee"], how="inner")\n    matched = matched[\n        matched["type_page"].eq(matched["type_comptes_resolu"])\n        | matched["type_page"].eq("a_controler")\n    ].copy()\n\n    validation_rows = []\n    for key, group in matched.groupby(\n        ["societe", "annee", "type_comptes_resolu", "variable"]\n    ):\n        # Médiane par origine pour réduire les répétitions du même montant.\n        current = group[group["origine"].eq("courant")]\n        comparative = group[group["origine"].eq("comparatif")]\n        current_value = current["valeur_mad"].median() if len(current) else np.nan\n        comparative_value = (\n            comparative["valeur_mad"].median() if len(comparative) else np.nan\n        )\n        if pd.notna(current_value) and pd.notna(comparative_value):\n            gap = abs(current_value - comparative_value) / max(\n                abs(current_value), abs(comparative_value), 1\n            )\n            final_value = np.median([current_value, comparative_value])\n            status = "valide_deux_publications" if gap <= 0.02 else "conflit_publications"\n        else:\n            gap = np.nan\n            final_value = (\n                current_value if pd.notna(current_value) else comparative_value\n            )\n            status = "une_seule_publication_a_revoir"\n        validation_rows.append({\n            "societe": key[0],\n            "annee": key[1],\n            "type_comptes_resolu": key[2],\n            "variable": key[3],\n            "valeur_courante_mediane_mad": current_value,\n            "valeur_comparative_mediane_mad": comparative_value,\n            "ecart_relatif_publications": gap,\n            "valeur_finale_mad": final_value,\n            "statut_validation": status,\n            "preuves_courantes": len(current),\n            "preuves_comparatives": len(comparative),\n        })\n    validation = pd.DataFrame(validation_rows)\n    validation = validation.merge(\n        banks,\n        on=["societe", "annee", "type_comptes_resolu"],\n        how="left",\n        validate="many_to_one",\n    )\n    validation["coherence_economique"] = np.where(\n        validation["variable"].eq("produit_net_bancaire"),\n        validation["valeur_finale_mad"].ge(validation["is_mad"]),\n        True,\n    )\n    validation.loc[\n        validation["statut_validation"].eq("valide_deux_publications")\n        & ~validation["coherence_economique"],\n        "statut_validation",\n    ] = "unite_incoherente_pnb_inferieur_is"\n    validated = validation[\n        validation["statut_validation"].eq("valide_deux_publications")\n    ].copy()\n    coverage = (\n        validated.groupby(["variable"])\n        .agg(\n            observations=("valeur_finale_mad", "size"),\n            entreprises=("societe", "nunique"),\n            annee_min=("annee", "min"),\n            annee_max=("annee", "max"),\n        )\n        .reset_index()\n    )\n    methodology = pd.DataFrame([\n        ["Tolérance", "2 % entre publication courante et comparative"],\n        ["Périmètre", "Identique au panel ou page à contrôler"],\n        ["Unités", "Seulement unité explicite"],\n        ["Montants PNB", "Entre 1 million et 100 milliards MAD"],\n        ["Cohérence PNB", "PNB supérieur ou égal à l\'IS de même périmètre"],\n        ["Statut utilisable", "valide_deux_publications uniquement"],\n        ["Conflits", "Conservés pour revue; exclus de la modélisation"],\n    ], columns=["element", "regle"])\n\n    with pd.ExcelWriter(OUTPUT, engine="openpyxl") as writer:\n        validated.to_excel(writer, sheet_name="Valeurs validees", index=False)\n        validation.to_excel(writer, sheet_name="Toutes validations", index=False)\n        matched.to_excel(writer, sheet_name="Preuves rapprochees", index=False)\n        coverage.to_excel(writer, sheet_name="Couverture", index=False)\n        methodology.to_excel(writer, sheet_name="Methodologie", index=False)\n    print("Valeurs validées :", len(validated))\n    print(coverage.to_string(index=False))\n    print("\\nStatuts :")\n    print(validation["statut_validation"].value_counts().to_string())\n    print(f"\\nCréé : {OUTPUT}")\n\n\nif __name__ == "__main__":\n    main()\n',
    '48_auditer_entreprises_sans_prevision_2026.py': '"""\nDiagnostiquer les entreprises du panel sans prévision d\'IS pour 2026.\n\nL\'audit distingue l\'absence d\'informations financières 2025 de l\'absence\nde la cible IS 2025. Il ne fabrique aucune valeur manquante : il indique\nla cause observable et l\'action à mener avant d\'étendre les prévisions.\n"""\n\nfrom pathlib import Path\n\nimport pandas as pd\n\n\nOUT = Path("data/output")\nPANEL_FILE = OUT / "diagnostic_panel_is_financier.xlsx"\nFINANCIAL_FILE = OUT / "variables_financieres_base_prevalidee_v16.xlsx"\nFORECAST_FILE = OUT / "previsions_is_2026.xlsx"\nOUTPUT_FILE = OUT / "audit_entreprises_sans_prevision_2026.xlsx"\n\nKEY_VARIABLES = [\n    "resultat_avant_impot",\n    "resultat_net",\n    "chiffre_affaires",\n    "total_actif",\n    "capitaux_propres",\n]\n\n\ndef join_non_empty(values):\n    """Assembler les noms de variables dans une cellule lisible."""\n    return ", ".join(values) if values else "Aucune"\n\n\ndef main():\n    """Créer l\'audit individuel et les tableaux de synthèse."""\n    panel = pd.read_excel(PANEL_FILE, sheet_name="Panel provisoire")\n    financial = pd.read_excel(\n        FINANCIAL_FILE, sheet_name="Base prévalidée large"\n    )\n    forecast = pd.read_excel(FORECAST_FILE, sheet_name="Previsions IS 2026")\n\n    panel_companies = sorted(panel["societe"].dropna().unique())\n    forecast_companies = set(forecast["societe"].dropna().unique())\n    missing_companies = [x for x in panel_companies if x not in forecast_companies]\n\n    rows = []\n    for company in missing_companies:\n        p = panel[panel["societe"].eq(company)].copy()\n        f = financial[financial["societe"].eq(company)].copy()\n        f2025 = f[f["annee"].eq(2025)].copy()\n\n        last_panel_year = int(p["annee"].max())\n        last_is_year = (\n            int(p.loc[p["is_mad"].notna(), "annee"].max())\n            if p["is_mad"].notna().any()\n            else pd.NA\n        )\n        last_financial_year = (\n            int(f["annee"].max()) if not f.empty else pd.NA\n        )\n\n        missing_key_variables = []\n        if not f2025.empty:\n            # Une seule ligne société-année-périmètre est attendue dans V16.\n            current = f2025.sort_values(\n                "nombre_variables_prevalidees", ascending=False\n            ).iloc[0]\n            missing_key_variables = [\n                variable\n                for variable in KEY_VARIABLES\n                if pd.isna(current.get(variable))\n            ]\n\n        has_financial_2025 = not f2025.empty\n        has_is_2025 = bool(\n            ((p["annee"].eq(2025)) & p["is_mad"].notna()).any()\n        )\n\n        if has_financial_2025 and not has_is_2025:\n            cause = "IS 2025 absent; informations financières 2025 disponibles"\n            priority = 1\n            action = (\n                "Rechercher/valider l\'IS 2025. À défaut, tester une prévision "\n                "directe sans IS retardé et signaler une confiance réduite."\n            )\n            potential = "Élevé"\n        elif last_financial_year == 2024:\n            cause = "Aucune information financière 2025; dernière année 2024"\n            priority = 2\n            action = (\n                "Collecter le rapport 2025. Ne pas confondre une prévision "\n                "2025 fondée sur 2024 avec une prévision 2026."\n            )\n            potential = "Moyen à élevé"\n        else:\n            cause = (\n                "Historique ancien ou entreprise sortie/transformée; dernière "\n                f"année financière {last_financial_year}"\n            )\n            priority = 3\n            action = (\n                "Vérifier le statut de cotation, changement de nom, fusion ou "\n                "radiation avant toute collecte et toute prévision."\n            )\n            potential = "À vérifier"\n\n        rows.append(\n            {\n                "societe": company,\n                "secteur": p["secteur"].dropna().iloc[-1]\n                if p["secteur"].notna().any()\n                else pd.NA,\n                "derniere_annee_panel": last_panel_year,\n                "derniere_annee_is": last_is_year,\n                "derniere_annee_financiere": last_financial_year,\n                "donnees_financieres_2025": "Oui" if has_financial_2025 else "Non",\n                "is_2025": "Oui" if has_is_2025 else "Non",\n                "variables_cles_manquantes_en_2025": (\n                    join_non_empty(missing_key_variables)\n                    if has_financial_2025\n                    else "Non applicable"\n                ),\n                "cause_observable": cause,\n                "priorite": priority,\n                "potentiel_extension_2026": potential,\n                "action_recommandee": action,\n            }\n        )\n\n    audit = pd.DataFrame(rows).sort_values(\n        ["priorite", "derniere_annee_financiere", "societe"],\n        ascending=[True, False, True],\n    )\n\n    cause_summary = (\n        audit.groupby(\n            ["priorite", "cause_observable", "potentiel_extension_2026"],\n            dropna=False,\n        )\n        .size()\n        .reset_index(name="nombre_entreprises")\n        .sort_values("priorite")\n    )\n\n    coverage = pd.DataFrame(\n        [\n            ["Entreprises dans le panel", len(panel_companies)],\n            ["Entreprises déjà prévues pour 2026", len(forecast_companies)],\n            ["Entreprises sans prévision", len(audit)],\n            [\n                "Sans prévision mais avec données financières 2025",\n                int(audit["donnees_financieres_2025"].eq("Oui").sum()),\n            ],\n            [\n                "Sans prévision, dernière année financière 2024",\n                int(audit["derniere_annee_financiere"].eq(2024).sum()),\n            ],\n            [\n                "Sans prévision, données financières antérieures à 2024",\n                int(audit["derniere_annee_financiere"].lt(2024).sum()),\n            ],\n        ],\n        columns=["indicateur", "nombre"],\n    )\n\n    with pd.ExcelWriter(OUTPUT_FILE, engine="openpyxl") as writer:\n        audit.to_excel(writer, sheet_name="Audit individuel", index=False)\n        cause_summary.to_excel(writer, sheet_name="Synthese causes", index=False)\n        coverage.to_excel(writer, sheet_name="Couverture", index=False)\n\n    print(coverage.to_string(index=False))\n    print("\\nPriorité 1 :")\n    print(\n        audit.loc[\n            audit["priorite"].eq(1),\n            [\n                "societe",\n                "derniere_annee_is",\n                "variables_cles_manquantes_en_2025",\n            ],\n        ].to_string(index=False)\n    )\n    print(f"\\nCréé : {OUTPUT_FILE}")\n\n\nif __name__ == "__main__":\n    main()\n',
    '49_controler_is_2025_priorite.py': '"""\nContrôler la présence de l\'IS 2025 pour les 14 entreprises prioritaires.\n\nLes classeurs IS reçus ont un décalage erroné dans leur répertoire ZIP.\nLe script crée une copie réparée dans data/output/repaired_input, sans jamais\nmodifier les fichiers originaux, puis recherche les noms exacts et proches.\n"""\n\nfrom difflib import SequenceMatcher\nfrom pathlib import Path\nimport re\nimport struct\nimport unicodedata\n\nimport pandas as pd\n\n\nINPUT = Path("data/input")\nOUTPUT = Path("data/output")\nREPAIRED = OUTPUT / "repaired_input"\nAUDIT_FILE = OUTPUT / "audit_entreprises_sans_prevision_2026.xlsx"\nOUTPUT_FILE = OUTPUT / "controle_is_2025_14_entreprises.xlsx"\n\n\ndef normalize(value):\n    """Normaliser les dénominations sans perdre le nom original."""\n    text = unicodedata.normalize("NFKD", str(value))\n    text = text.encode("ascii", "ignore").decode().lower()\n    return " ".join(re.sub(r"[^a-z0-9]+", " ", text).split())\n\n\ndef repair_central_directory(source, destination):\n    """Corriger uniquement l\'adresse du répertoire central d\'un fichier XLSX."""\n    content = bytearray(source.read_bytes())\n    end_record = content.rfind(b"PK\\x05\\x06")\n    central_directory = content.find(b"PK\\x01\\x02")\n    if end_record < 0 or central_directory < 0:\n        raise ValueError(f"Structure XLSX introuvable : {source}")\n\n    # Dans EOCD, la taille et le décalage du répertoire central commencent\n    # respectivement aux octets 12 et 16.\n    struct.pack_into("<L", content, end_record + 12, end_record - central_directory)\n    struct.pack_into("<L", content, end_record + 16, central_directory)\n    destination.write_bytes(content)\n\n\ndef read_is_workbook(path):\n    """Mettre la base IS au format société-année-valeur."""\n    wide = pd.read_excel(path, sheet_name=0, header=2)\n    company_column = wide.columns[0]\n    long = wide.melt(\n        id_vars=[company_column], var_name="annee", value_name="is_mad"\n    ).rename(columns={company_column: "societe_is"})\n    long["annee"] = pd.to_numeric(long["annee"], errors="coerce")\n    long["is_mad"] = pd.to_numeric(long["is_mad"], errors="coerce")\n    long = long.dropna(subset=["societe_is", "annee"])\n    long["annee"] = long["annee"].astype(int)\n    return wide, long\n\n\ndef main():\n    """Réparer les sources et rechercher les 14 entreprises prioritaires."""\n    REPAIRED.mkdir(parents=True, exist_ok=True)\n    sources = sorted(INPUT.glob("IS*.xlsx"))\n    repaired_sources = []\n    for source in sources:\n        destination = REPAIRED / source.name\n        repair_central_directory(source, destination)\n        repaired_sources.append(destination)\n\n    audit = pd.read_excel(AUDIT_FILE, sheet_name="Audit individuel")\n    priority = audit[audit["priorite"].eq(1)].copy()\n\n    details = []\n    source_summaries = []\n    for source in repaired_sources:\n        wide, long = read_is_workbook(source)\n        names = long["societe_is"].dropna().unique().tolist()\n        source_summaries.append(\n            {\n                "source_reparee": source.name,\n                "nombre_societes": len(names),\n                "annee_min": long["annee"].min(),\n                "annee_max": long["annee"].max(),\n                "valeurs_is_2025": int(\n                    (long["annee"].eq(2025) & long["is_mad"].notna()).sum()\n                ),\n            }\n        )\n\n        for company in priority["societe"]:\n            company_norm = normalize(company)\n            ranked = sorted(\n                [\n                    (\n                        SequenceMatcher(\n                            None, company_norm, normalize(candidate)\n                        ).ratio(),\n                        candidate,\n                    )\n                    for candidate in names\n                ],\n                reverse=True,\n            )\n            score, matched_name = ranked[0]\n            company_history = long[long["societe_is"].eq(matched_name)]\n            value_2025 = company_history.loc[\n                company_history["annee"].eq(2025), "is_mad"\n            ]\n            non_missing = company_history.dropna(subset=["is_mad"])\n            details.append(\n                {\n                    "societe_panel": company,\n                    "source_reparee": source.name,\n                    "meilleur_nom_source_is": matched_name,\n                    "score_similarite": round(score, 4),\n                    "derniere_annee_is_non_nulle": (\n                        int(non_missing["annee"].max())\n                        if not non_missing.empty\n                        else pd.NA\n                    ),\n                    "is_2025_source_mad": (\n                        value_2025.iloc[0]\n                        if not value_2025.empty\n                        and pd.notna(value_2025.iloc[0])\n                        else pd.NA\n                    ),\n                    "statut": (\n                        "IS 2025 retrouvé dans la source"\n                        if not value_2025.empty\n                        and pd.notna(value_2025.iloc[0])\n                        else "IS 2025 absent dans la source"\n                    ),\n                }\n            )\n\n    detail = pd.DataFrame(details).sort_values(\n        ["societe_panel", "source_reparee"]\n    )\n    summary = pd.DataFrame(source_summaries)\n    to_research = (\n        detail.groupby("societe_panel")\n        .agg(\n            is_2025_retrouve=(\n                "is_2025_source_mad",\n                lambda x: "Oui" if x.notna().any() else "Non",\n            ),\n            meilleur_score=("score_similarite", "max"),\n            noms_candidats=(\n                "meilleur_nom_source_is",\n                lambda x: " | ".join(pd.unique(x.astype(str))),\n            ),\n            derniere_annee_is_source=("derniere_annee_is_non_nulle", "max"),\n        )\n        .reset_index()\n    )\n    to_research["action_suivante"] = to_research["is_2025_retrouve"].map(\n        {\n            "Oui": "Valider le nom et le périmètre avant intégration",\n            "Non": "Rechercher l\'impôt courant/IS dans le rapport annuel 2025",\n        }\n    )\n\n    with pd.ExcelWriter(OUTPUT_FILE, engine="openpyxl") as writer:\n        to_research.to_excel(writer, sheet_name="Synthese 14 entreprises", index=False)\n        detail.to_excel(writer, sheet_name="Controle deux sources", index=False)\n        summary.to_excel(writer, sheet_name="Etat sources reparees", index=False)\n\n    print(summary.to_string(index=False))\n    print("\\nContrôle des 14 entreprises :")\n    print(to_research.to_string(index=False))\n    print(f"\\nCréé : {OUTPUT_FILE}")\n\n\nif __name__ == "__main__":\n    main()\n',
    '50_integrer_is_2025_14_entreprises.py': '"""\nIntégrer dans le panel les 14 montants d\'IS 2025 vérifiés dans les rapports.\n\nChaque valeur est accompagnée du périmètre, de l\'unité publiée et de la page\nde preuve. Le script sauvegarde le panel précédent avant de le mettre à jour.\n"""\n\nfrom pathlib import Path\nimport shutil\n\nimport pandas as pd\n\n\nOUT = Path("data/output")\nPANEL_FILE = OUT / "diagnostic_panel_is_financier.xlsx"\nBACKUP_FILE = OUT / "diagnostic_panel_is_financier_avant_ajout_is_2025.xlsx"\nFINANCIAL_FILE = OUT / "variables_financieres_base_prevalidee_v16.xlsx"\nCONTROL_FILE = OUT / "is_2025_14_entreprises_valide.xlsx"\n\n# Montants positifs en MAD. Les valeurs publiées en milliers de MAD sont\n# multipliées par 1 000. Le périmètre suit celui de la série IS historique.\nVERIFIED = [\n    ("Afriquia Gaz", "sociaux", 336_655_512.00, 35, "MAD"),\n    ("CNIA SAADA", "sociaux", 153_096_560.30, 5, "MAD"),\n    ("Colorado", "sociaux", 20_373_949.00, 14, "MAD"),\n    ("Cosumar", "sociaux", 375_170_429.00, 138, "MAD"),\n    ("Crédit du Maroc", "consolides", 680_270_000.00, 13, "milliers MAD"),\n    ("Fenie Brossette", "sociaux", 6_155_337.00, 45, "MAD"),\n    ("Holcim", "consolides", 1_155_515_000.00, 81, "milliers MAD"),\n    ("IMMORENTE INVEST", "sociaux", 125_403.00, 24, "MAD"),\n    ("LABEL VIE", "sociaux", 237_829_644.28, 54, "MAD"),\n    ("Maghreb Oxygène", "sociaux", 1_418_379.00, 28, "MAD"),\n    ("MarocTelecom", "sociaux", 2_400_505_000.00, 81, "milliers MAD"),\n    ("SALAFIN", "sociaux", 95_326_000.00, 69, "milliers MAD"),\n    ("Sofac-Crédit", "sociaux", 102_968_000.00, 55, "milliers MAD"),\n    ("Unimer", "sociaux", 1_828_143.00, 26, "MAD"),\n]\n\n\ndef main():\n    """Ajouter les lignes vérifiées et conserver toutes les feuilles d\'audit."""\n    old_workbook = {\n        sheet: pd.read_excel(PANEL_FILE, sheet_name=sheet)\n        for sheet in pd.ExcelFile(PANEL_FILE).sheet_names\n    }\n    panel = old_workbook["Panel provisoire"].copy()\n    financial = pd.read_excel(FINANCIAL_FILE, sheet_name=0)\n\n    controls = []\n    additions = []\n    for company, scope, tax, page, published_unit in VERIFIED:\n        candidates = financial[\n            financial["societe"].eq(company)\n            & financial["annee"].eq(2025)\n            & financial["type_comptes_resolu"].eq(scope)\n        ].copy()\n        if len(candidates) != 1:\n            raise ValueError(\n                f"{company}: {len(candidates)} ligne(s) financière(s) trouvée(s)"\n            )\n        row = candidates.iloc[0].copy()\n        row["societe_is"] = company\n        row["score_correspondance_nom"] = 1.0\n        row["methode_correspondance_nom"] = "contrôle ciblé rapport 2025"\n        row["is_mad"] = tax\n        row["statut_perimetre_is"] = "vérifié_par_impôt_du_pdf"\n        row["ecart_identite_fiscale"] = pd.NA\n        row["is_implicite_mad"] = (\n            row["resultat_avant_impot"] - row["resultat_net"]\n            if pd.notna(row["resultat_avant_impot"])\n            and pd.notna(row["resultat_net"])\n            else pd.NA\n        )\n        additions.append(row)\n        controls.append(\n            {\n                "societe": company,\n                "annee": 2025,\n                "type_comptes": scope,\n                "is_2025_mad": tax,\n                "page_rapport": page,\n                "unite_publiee": published_unit,\n                "source": "Rapport financier annuel 2025 téléchargé",\n                "statut": "Validé pour intégration",\n            }\n        )\n\n    additions = pd.DataFrame(additions)\n    keys = ["societe", "annee", "type_comptes_resolu"]\n    panel = panel[\n        ~panel.set_index(keys).index.isin(additions.set_index(keys).index)\n    ]\n    panel = pd.concat([panel, additions], ignore_index=True, sort=False)\n    panel = panel.sort_values(["societe", "annee"]).reset_index(drop=True)\n\n    if panel.duplicated(keys).any():\n        raise ValueError("Doublon société-année-périmètre après intégration")\n\n    shutil.copy2(PANEL_FILE, BACKUP_FILE)\n    with pd.ExcelWriter(PANEL_FILE, engine="openpyxl") as writer:\n        panel.to_excel(writer, sheet_name="Panel provisoire", index=False)\n        for sheet, data in old_workbook.items():\n            if sheet != "Panel provisoire":\n                data.to_excel(writer, sheet_name=sheet, index=False)\n\n    control = pd.DataFrame(controls)\n    with pd.ExcelWriter(CONTROL_FILE, engine="openpyxl") as writer:\n        control.to_excel(writer, sheet_name="IS 2025 validés", index=False)\n\n    print("Lignes ajoutées :", len(additions))\n    print("Entreprises 2025 avec IS :", panel.loc[\n        panel["annee"].eq(2025) & panel["is_mad"].notna(), "societe"\n    ].nunique())\n    print(control[["societe", "type_comptes", "is_2025_mad"]].to_string(index=False))\n    print(f"Panel mis à jour : {PANEL_FILE}")\n    print(f"Sauvegarde : {BACKUP_FILE}")\n    print(f"Contrôle : {CONTROL_FILE}")\n\n\nif __name__ == "__main__":\n    main()\n',
    '51_integrer_is_2025_trois_societes_et_statut_lydec.py': '"""\nAjouter les données 2025 de Balima, Cartier Saada et Microdata au panel.\n\nLydec est conservée dans l\'historique d\'apprentissage, mais explicitement\nexclue de l\'univers opérationnel 2026 car son titre a été radié de la cote.\n"""\n\nfrom pathlib import Path\nimport shutil\n\nimport pandas as pd\n\n\nOUT = Path("data/output")\nPANEL_FILE = OUT / "diagnostic_panel_is_financier.xlsx"\nBACKUP_FILE = OUT / "diagnostic_panel_avant_ajout_3_societes_2025.xlsx"\nCONTROL_FILE = OUT / "controle_extension_previsions_3_societes_et_lydec.xlsx"\n\nVALUES = [\n    {\n        "societe": "Balima",\n        "type_comptes_resolu": "consolides",\n        "chiffre_affaires": 50_984_600.14,\n        "resultat_avant_impot": 15_123_586.60,\n        "resultat_net": 10_855_773.60,\n        "is_mad": 4_267_813.00,\n        "page_is": 13,\n        "cloture": "31/12/2025",\n    },\n    {\n        "societe": "Cartier Saada",\n        "type_comptes_resolu": "sociaux",\n        "chiffre_affaires": 296_694_031.26,\n        "resultat_avant_impot": 6_491_136.56,\n        "resultat_net": 5_736_516.56,\n        "is_mad": 754_620.00,\n        "page_is": 62,\n        "cloture": "31/03/2025",\n    },\n    {\n        "societe": "Microdata",\n        "type_comptes_resolu": "sociaux",\n        "chiffre_affaires": 979_416_352.36,\n        "resultat_avant_impot": 91_471_712.96,\n        "resultat_net": 69_547_790.96,\n        "is_mad": 21_923_922.00,\n        "page_is": 14,\n        "cloture": "31/12/2025",\n    },\n]\n\n\ndef main():\n    """Créer trois lignes 2025 contrôlées et le registre de l\'univers 2026."""\n    workbook = {\n        sheet: pd.read_excel(PANEL_FILE, sheet_name=sheet)\n        for sheet in pd.ExcelFile(PANEL_FILE).sheet_names\n    }\n    panel = workbook["Panel provisoire"].copy()\n    additions = []\n    controls = []\n\n    for value in VALUES:\n        history = panel[panel["societe"].eq(value["societe"])].sort_values("annee")\n        if history.empty:\n            raise ValueError(f"Historique absent : {value[\'societe\']}")\n        row = pd.Series({column: pd.NA for column in panel.columns})\n        last = history.iloc[-1]\n        # Les informations structurelles stables proviennent de la dernière ligne.\n        for column in ["societe", "secteur", "societe_is"]:\n            row[column] = last[column]\n        row["annee"] = 2025\n        row["type_comptes_resolu"] = value["type_comptes_resolu"]\n        row["chiffre_affaires"] = value["chiffre_affaires"]\n        row["resultat_avant_impot"] = value["resultat_avant_impot"]\n        row["resultat_net"] = value["resultat_net"]\n        row["is_mad"] = value["is_mad"]\n        row["nombre_variables_prevalidees"] = 3\n        row["score_correspondance_nom"] = 1.0\n        row["methode_correspondance_nom"] = "contrôle ciblé rapport 2025"\n        row["statut_perimetre_is"] = "vérifié_par_impôt_du_pdf"\n        row["is_implicite_mad"] = (\n            value["resultat_avant_impot"] - value["resultat_net"]\n        )\n        additions.append(row)\n        controls.append(\n            {\n                "societe": value["societe"],\n                "statut_univers_2026": "Incluse",\n                "cloture_des_comptes": value["cloture"],\n                "type_comptes": value["type_comptes_resolu"],\n                "is_2025_mad": value["is_mad"],\n                "page_source": value["page_is"],\n                "observation": (\n                    "Exercice à cheval affecté à 2025"\n                    if value["societe"] == "Cartier Saada"\n                    else "Exercice calendaire"\n                ),\n            }\n        )\n\n    additions = pd.DataFrame(additions)\n    keys = ["societe", "annee", "type_comptes_resolu"]\n    panel = panel[\n        ~panel.set_index(keys).index.isin(additions.set_index(keys).index)\n    ]\n    panel = pd.concat([panel, additions], ignore_index=True)\n    panel = panel.sort_values(["societe", "annee"]).reset_index(drop=True)\n\n    controls.append(\n        {\n            "societe": "Lydec",\n            "statut_univers_2026": "Exclue",\n            "cloture_des_comptes": pd.NA,\n            "type_comptes": pd.NA,\n            "is_2025_mad": pd.NA,\n            "page_source": pd.NA,\n            "observation": (\n                "Titre radié de la Bourse de Casablanca après l\'OPR de 2022; "\n                "historique conservé uniquement pour l\'apprentissage"\n            ),\n        }\n    )\n    control = pd.DataFrame(controls)\n\n    shutil.copy2(PANEL_FILE, BACKUP_FILE)\n    with pd.ExcelWriter(PANEL_FILE, engine="openpyxl") as writer:\n        panel.to_excel(writer, sheet_name="Panel provisoire", index=False)\n        for sheet, data in workbook.items():\n            if sheet != "Panel provisoire":\n                data.to_excel(writer, sheet_name=sheet, index=False)\n    with pd.ExcelWriter(CONTROL_FILE, engine="openpyxl") as writer:\n        control.to_excel(writer, sheet_name="Contrôle extension", index=False)\n\n    print(control.to_string(index=False))\n    print("Entreprises avec IS 2025 :", panel.loc[\n        panel["annee"].eq(2025) & panel["is_mad"].notna(), "societe"\n    ].nunique())\n    print(f"Panel : {PANEL_FILE}")\n    print(f"Sauvegarde : {BACKUP_FILE}")\n    print(f"Contrôle : {CONTROL_FILE}")\n\n\nif __name__ == "__main__":\n    main()\n',
    '52_classer_univers_boursier_2026.py': '"""Documenter le statut boursier des 13 sociétés historiques sans prévision."""\n\nfrom pathlib import Path\n\nimport pandas as pd\n\n\nOUTPUT = Path("data/output/statut_13_societes_historiques_univers_2026.xlsx")\n\nROWS = [\n    ["TIMAR", "Exclue", "Radiée après OPR en 2024", "Ne pas prévoir"],\n    ["Dari couspate", "À compléter", "Toujours cotée et active en 2026", "Collecter rapport et IS 2025"],\n    ["SRM", "À compléter", "Toujours cotée et publications 2026", "Collecter le véritable rapport 2025"],\n    ["Maroc Leasing", "À compléter", "Toujours cotée en 2026", "Extraire IS 2025 du rapport disponible"],\n    ["DELATTRE LEVIVIER MAROC", "Cas spécial", "Titre suspendu depuis janvier 2023; toujours inscrit", "Ne pas produire de prévision standard sans comptes récents"],\n    ["Nexans Maroc", "Exclue", "Offre publique de retrait en 2021", "Ne pas prévoir"],\n    ["PROMOPHARM", "À compléter", "Toujours cotée et active en 2026", "Extraire IS 2025 du rapport disponible"],\n    ["CGI", "Exclue", "Retrait de la cote à la suite de l\'OPR de 2015", "Ne pas prévoir"],\n    ["Samir", "Exclue du modèle standard", "Cotation suspendue; liquidation judiciaire", "Traiter séparément, sans prévision fiscale ordinaire"],\n    ["SCE", "Exclue", "Ancienne valeur; société scindée en 2018 et absente de la cote actuelle", "Ne pas prévoir"],\n    ["IB Maroc.com", "À compléter", "Toujours cotée et négociée en 2026", "Rechercher et collecter les comptes 2025"],\n    ["ONA", "Exclue", "Radiée de la cote en août 2010", "Ne pas prévoir"],\n    ["Les grandes marques et conserveries chérifiennes", "Exclue", "LGMC retirée de la cote en 2010", "Ne pas prévoir"],\n]\n\n\ndef main():\n    status = pd.DataFrame(\n        ROWS,\n        columns=["societe", "statut_univers_2026", "justification", "action"],\n    )\n    summary = (\n        status.groupby("statut_univers_2026")\n        .size()\n        .reset_index(name="nombre_societes")\n    )\n    with pd.ExcelWriter(OUTPUT, engine="openpyxl") as writer:\n        status.to_excel(writer, sheet_name="Statut individuel", index=False)\n        summary.to_excel(writer, sheet_name="Synthese", index=False)\n    print(summary.to_string(index=False))\n    print(f"Créé : {OUTPUT}")\n\n\nif __name__ == "__main__":\n    main()\n',
    '53_auditer_lignes_rouges_base_is.py': '"""Construit le registre d\'audit des sociétés signalées en rouge dans la base IS.\n\nLe registre distingue :\n1. les titres réellement radiés ;\n2. les sociétés ayant une continuité juridique/comptable avec une société actuelle ;\n3. les titres encore présents mais suspendus ;\n4. les émetteurs obligataires qui ne sont pas des actions cotées.\n"""\n\nfrom pathlib import Path\n\nfrom openpyxl import Workbook\nfrom openpyxl.styles import Alignment, Font, PatternFill\nfrom openpyxl.utils import get_column_letter\n\n\nSORTIE = Path("data/output/audit_lignes_rouges_base_is.xlsx")\n\nCOLONNES = [\n    "Société dans la base IS",\n    "Statut vérifié en 2026",\n    "Événement / date",\n    "Successeur ou série actuelle",\n    "Décision pour l\'univers 2026",\n    "Traitement des données historiques",\n    "Niveau de preuve",\n    "Source principale",\n]\n\nLIGNES = [\n    [\n        "Berliet Maroc",\n        "Radiée de la cote",\n        "OPR et radiation en 2011",\n        "",\n        "Exclure de la population active 2026",\n        "Conserver seulement comme observation historique, avec indicateur de sortie",\n        "Officiel AMMC",\n        "https://www.ammc.ma/fr/espace-emetteurs/berliet-maroc",\n    ],\n    [\n        "Branoma",\n        "Absorbée",\n        "Absorption par Société des Boissons du Maroc en 2014",\n        "Société des Boissons du Maroc (SBM)",\n        "Ne pas compter Branoma comme entreprise active distincte",\n        "Ne pas additionner automatiquement Branoma et SBM; documenter la rupture de périmètre",\n        "Officiel AMMC / rapport SBM",\n        "https://www.ammc.ma/fr/espace-emetteurs/liste-des-emetteurs/2834",\n    ],\n    [\n        "Diac Salaf",\n        "Titre encore référencé; cotation suspendue",\n        "Suspensions reconduites; instrument DIS toujours référencé par l\'AMMC",\n        "Diac Salaf",\n        "Cas spécial à conserver dans le registre, hors prévision standard tant que les comptes récents manquent",\n        "Ne surtout pas classer comme radiée sur la seule couleur rouge",\n        "Officiel AMMC",\n        "https://www.ammc.ma/fr/instruments-financiers/actions/action-diac-salaf",\n    ],\n    [\n        "Fertima",\n        "Radiée de la cote",\n        "OPR puis radiation en 2014",\n        "",\n        "Exclure de la population active 2026",\n        "Conserver seulement dans l\'historique avant la sortie",\n        "Information de marché concordante; date à archiver avec l\'avis de radiation",\n        "https://www.ammc.ma/fr/radiation",\n    ],\n    [\n        "La Marocaine Vie",\n        "Retirée de la cote",\n        "Offre publique de retrait visée le 08/01/2009",\n        "La Marocaine Vie (non cotée)",\n        "Exclure de la population d\'actions cotées en 2026",\n        "Conserver l\'historique jusqu\'au retrait, sans la confondre avec une autre société cotée",\n        "Officiel AMMC",\n        "https://www.ammc.ma/fr/espace-emetteurs/liste-des-emetteurs/2782",\n    ],\n    [\n        "LGMC",\n        "Retirée de la cote",\n        "Offre publique de retrait en 2010",\n        "",\n        "Exclure de la population active 2026",\n        "Historique séparé; ne pas le fusionner automatiquement avec Mutandis",\n        "Officiel AMMC",\n        "https://v8.ammc.ma/sites/default/files/Note_d%27info_LGMC_vis%C3%A9e.pdf",\n    ],\n    [\n        "Mediaco Maroc",\n        "Radiée de la cote",\n        "Offre publique de retrait; statut AMMC: Radié de la bourse",\n        "",\n        "Exclure de la population active 2026",\n        "Conserver seulement comme historique",\n        "Officiel AMMC",\n        "https://www.ammc.ma/fr/espace-emetteurs/liste-des-emetteurs/2803",\n    ],\n    [\n        "Matel PC Market",\n        "Société absorbante renommée",\n        "Fusion-absorption de Distrisoft approuvée le 29/04/2010; nouveau nom Disway",\n        "Disway",\n        "Rattacher l\'identité à Disway, sans créer deux entreprises après 2010",\n        "Traiter 2010 comme rupture de périmètre et contrôler les doublons Matel/Distrisoft",\n        "Officiel AMMC",\n        "https://www.ammc.ma/sites/default/files/NI_BT_Disway.pdf",\n    ],\n    [\n        "ONA",\n        "Radiée puis absorbée",\n        "Radiation en 2010; fusion-absorption par SNI avec effet rétroactif au 01/10/2010",\n        "SNI puis Al Mada (non cotée)",\n        "Exclure de la population active 2026",\n        "Conserver comme série historique distincte; ne pas la prolonger artificiellement",\n        "Officiel AMMC",\n        "https://www.ammc.ma/fr/node/9152",\n    ],\n    [\n        "Samir",\n        "Titre référencé mais suspendu; société en liquidation judiciaire",\n        "Liquidation judiciaire annoncée en avril 2016",\n        "Samir",\n        "Exclure du modèle opérationnel standard 2026; conserver comme cas spécial",\n        "Ne pas imputer des variables d\'exploitation normales",\n        "Officiel AMMC",\n        "https://www.ammc.ma/fr/espace-emetteurs/samir",\n    ],\n    [\n        "SNI",\n        "Radiée de la cote",\n        "Radiation décidée le 16/06/2010, effective le 19/08/2010",\n        "Al Mada (non cotée)",\n        "Exclure de la population active 2026",\n        "Conserver comme historique; changement d\'identité et de périmètre à documenter",\n        "Officiel AMMC",\n        "https://v8.ammc.ma/sites/default/files/NI_AUG_Capital_AWB_007_2012_D.pdf",\n    ],\n    [\n        "Société Chérifienne d\'Engrais (SCE)",\n        "Retirée de la cote",\n        "Offre publique de retrait finalisée en 2013",\n        "",\n        "Exclure de la population active 2026",\n        "Conserver l\'historique jusqu\'au retrait",\n        "Officiel AMMC (mention de finalisation de l\'OPR)",\n        "https://www.ammc.ma/sites/default/files/NI_CDM_022_2014.pdf",\n    ],\n    [\n        "Wafa bank",\n        "Fusionnée",\n        "Fusion avec Banque Commerciale du Maroc effective le 01/09/2004",\n        "Attijariwafa bank",\n        "Utiliser Attijariwafa bank comme société active; ne pas compter Wafabank séparément",\n        "Harmoniser l\'identifiant, avec indicateur de rupture de périmètre en 2004",\n        "Officiel AMMC / document de référence AWB",\n        "https://v8.ammc.ma/sites/default/files/DR_AWB_007_2025.pdf",\n    ],\n    [\n        "Afrilub",\n        "Émetteur obligataire, pas une action cotée",\n        "AMMC: compartiment Marché obligataire; aucune date d\'introduction en actions",\n        "",\n        "Exclure de l\'univers des actions cotées 2026",\n        "Garder éventuellement dans une base obligataire séparée",\n        "Officiel AMMC",\n        "https://www.ammc.ma/fr/espace-emetteurs/afrilub",\n    ],\n]\n\n\ndef construire_classeur() -> None:\n    SORTIE.parent.mkdir(parents=True, exist_ok=True)\n    wb = Workbook()\n    ws = wb.active\n    ws.title = "Audit_14_rouges"\n    ws.append(COLONNES)\n    for ligne in LIGNES:\n        ws.append(ligne)\n\n    bleu = PatternFill("solid", fgColor="1F4E78")\n    for cellule in ws[1]:\n        cellule.fill = bleu\n        cellule.font = Font(color="FFFFFF", bold=True)\n        cellule.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)\n\n    couleurs = {\n        "Radiée": "F4CCCC",\n        "Retirée": "F4CCCC",\n        "Fusionnée": "FFF2CC",\n        "Absorbée": "FFF2CC",\n        "Société absorbante": "D9EAD3",\n        "Titre encore": "CFE2F3",\n        "Titre référencé": "CFE2F3",\n        "Émetteur obligataire": "EAD1DC",\n    }\n    for row in range(2, ws.max_row + 1):\n        statut = ws.cell(row, 2).value\n        for prefixe, couleur in couleurs.items():\n            if statut.startswith(prefixe):\n                ws.cell(row, 2).fill = PatternFill("solid", fgColor=couleur)\n                break\n        for col in range(1, ws.max_column + 1):\n            ws.cell(row, col).alignment = Alignment(vertical="top", wrap_text=True)\n\n    largeurs = [31, 34, 43, 31, 48, 55, 35, 65]\n    for i, largeur in enumerate(largeurs, start=1):\n        ws.column_dimensions[get_column_letter(i)].width = largeur\n    ws.freeze_panes = "A2"\n    ws.auto_filter.ref = ws.dimensions\n    ws.row_dimensions[1].height = 34\n\n    synthese = wb.create_sheet("Synthese")\n    synthese.append(["Catégorie", "Nombre", "Conséquence"])\n    synthese.append(["Exclues de la population active 2026", 10, "Radiées, retirées ou non cotées en actions"])\n    synthese.append(["Continuité avec une société actuelle", 3, "Branoma→SBM; Matel→Disway; Wafabank→Attijariwafa bank"])\n    synthese.append(["Cas encore référencé mais spécial", 1, "DIAC Salaf: suspendue, à ne pas traiter comme radiée"])\n    synthese.append(["Cas spécial hors modèle standard parmi les exclues", 1, "Samir: liquidation judiciaire"])\n    synthese.append([])\n    synthese.append(["Conclusion méthodologique"])\n    synthese.append([\n        "La couleur rouge n\'est pas une preuve de radiation. L\'identité juridique, la cote actuelle et les "\n        "fusions doivent être vérifiées avant d\'entraîner ou de prévoir le modèle."\n    ])\n    for cellule in synthese[1]:\n        cellule.fill = bleu\n        cellule.font = Font(color="FFFFFF", bold=True)\n    synthese.column_dimensions["A"].width = 48\n    synthese.column_dimensions["B"].width = 14\n    synthese.column_dimensions["C"].width = 90\n    for row in synthese.iter_rows():\n        for cellule in row:\n            cellule.alignment = Alignment(vertical="top", wrap_text=True)\n\n    wb.save(SORTIE)\n    print(f"Fichier créé : {SORTIE.resolve()}")\n\n\nif __name__ == "__main__":\n    construire_classeur()\n',
    '54_construire_univers_final_2026.py': '"""Construire l\'univers final des entreprises à prévoir en 2026.\n\nLe fichier IS original présente un index ZIP décalé. Une copie technique est\nréparée sans modifier la source, puis chaque société est comparée au panel\nfinancier et au fichier des prévisions déjà produites.\n"""\n\nfrom pathlib import Path\nimport re\nimport struct\nimport unicodedata\nfrom zipfile import BadZipFile\n\nimport pandas as pd\nfrom openpyxl import load_workbook\nfrom openpyxl.styles import Alignment, Font, PatternFill\nfrom openpyxl.utils import get_column_letter\n\n\nINPUT = Path("data/input/IS sociétés cotées origine (1).xlsx")\nOUT = Path("data/output")\nREPAIRED = OUT / "repaired_input/IS_societes_cotees_origine_repare_correctement.xlsx"\nPANEL_FILE = OUT / "diagnostic_panel_is_financier.xlsx"\nFORECAST_FILE = OUT / "previsions_is_2026.xlsx"\nOUTPUT_FILE = OUT / "univers_final_previsions_is_2026.xlsx"\nCOMPANY_REGISTRY = Path("data/input/societes.xlsx")\n\n# Sociétés visibles dans la base IS transmise mais absentes de l\'ancien registre\n# de téléchargement. Elles sont ajoutées explicitement pour ne pas réduire\n# artificiellement l\'univers à cause du classeur binaire endommagé.\nCAPTURE_ADDITIONS = [\n    "AFMA",\n    "BCP",\n    "JALU (JET CONTRACTORS)",\n    "S2M",\n    "TAQA MOROCCO",\n    "TOTAL MAROC",\n    "ARADEI Capital",\n    "AKDITAL",\n    "CREDIT AGRICOLE DU MAROC",\n]\n\n\ndef normalize(value):\n    """Uniformiser accents, ponctuation et espaces pour comparer les noms."""\n    text = unicodedata.normalize("NFKD", str(value))\n    text = "".join(c for c in text if not unicodedata.combining(c)).lower()\n    return " ".join(re.sub(r"[^a-z0-9]+", " ", text).split())\n\n\ndef repair_xlsx(source, destination):\n    """Corriger le répertoire central ZIP dans une copie du classeur.\n\n    Certains octets ajoutés au fichier ont rendu erronés la taille et l\'adresse\n    du répertoire central. On repère sa vraie première signature à partir de la\n    fin, puis on actualise uniquement les deux champs de l\'enregistrement EOCD.\n    """\n    content = bytearray(source.read_bytes())\n    end = content.rfind(b"PK\\x05\\x06")\n    if end < 0:\n        raise ValueError("Fin du conteneur XLSX introuvable")\n\n    # Les entrées du répertoire central se trouvent immédiatement avant EOCD.\n    # Ce classeur a une fausse signature environ 60 Ko plus tôt dans une feuille\n    # compressée : limiter la recherche aux 10 derniers Ko l\'écarte sûrement.\n    start = content.find(b"PK\\x01\\x02", max(0, end - 10_000), end)\n    if start < 0:\n        raise ValueError("Répertoire central XLSX introuvable")\n\n    struct.pack_into("<L", content, end + 12, end - start)\n    struct.pack_into("<L", content, end + 16, start)\n    destination.parent.mkdir(parents=True, exist_ok=True)\n    destination.write_bytes(content)\n\n\n# Continuités d\'identité vérifiées ou libellés déjà employés dans le panel.\nALIASES = {\n    "wafa bank": "Attijari wafa bank",\n    "wafabank": "Attijari wafa bank",\n    "matel pc market": "DISTY RFA",\n    "branoma": "Brasseries du Maroc",\n    "societe des boissons du maroc sbm": "Brasseries du Maroc",\n    "bmce bank bank of africa": "BMCE BANK",\n    "agma lahlou tazi": "AGMA",\n    "alliances developpement immobilier adi": "ALLIANCES",\n    "douja prom addoha": "Addoha",\n    "ciments du maroc": "Ciments du Maroc",\n    "maroc telecom itissalat almaghrib": "MarocTelecom",\n    "miniere touissit": "MINIERE TOUISSIT",\n    "sodep marsa maroc": "SODEP-Marsa Maroc",\n    "cnia saada saham assurances": "CNIA SAADA",\n    "les eaux minerales d oulmes": "Oulmès",\n    "ou lmes": "Oulmès",\n    "afriquia gaz": "Afriquia Gaz",\n}\n\n# Statuts confirmés lors des audits AMMC. Les historiques restent conservés :\n# seule leur appartenance à la population active 2026 est modifiée.\nEXCLUSIONS = {\n    "berliet maroc": "Radiée de la cote",\n    "fertima": "Radiée de la cote",\n    "la marocaine vie": "Retirée de la cote en 2009",\n    "les grandes marques et conserveries cherifiennes": "LGMC retirée de la cote",\n    "mediaco maroc": "Radiée de la cote",\n    "ona": "Radiée puis absorbée en 2010",\n    "sni": "Radiée de la cote en 2010",\n    "societe cherifienne d engrais": "SCE retirée de la cote",\n    "sce": "SCE retirée de la cote",\n    "afrilub": "Émetteur obligataire, pas une action cotée",\n    "cgi": "Retirée de la cote après OPR",\n    "nexans maroc": "Retirée de la cote après OPR",\n    "timar": "Radiée après OPR",\n    "lydec": "Radiée de la cote",\n}\n\nCONTINUITES = {\n    "branoma": "Absorbée par SBM : utiliser Brasseries du Maroc",\n    "matel pc market": "Matel est devenue Disway : utiliser la série actuelle",\n    "wafa bank": "Fusionnée : utiliser Attijariwafa bank",\n    "wafabank": "Fusionnée : utiliser Attijariwafa bank",\n}\n\nCAS_SPECIAUX = {\n    "diac salaf": "Titre référencé mais suspendu; comptes récents à vérifier",\n    "samir": "Liquidation judiciaire; hors modèle opérationnel standard",\n    "delattre levivier maroc dlm": "Titre suspendu; pas de prévision standard sans comptes récents",\n    "delattre levivier maroc": "Titre suspendu; pas de prévision standard sans comptes récents",\n}\n\n\ndef find_equivalent(source_name, candidates):\n    """Trouver un libellé identique après normalisation, sans fuzzy matching."""\n    source_norm = normalize(source_name)\n    canonical = ALIASES.get(source_norm, source_name)\n    candidate_index = {normalize(x): x for x in candidates}\n    return candidate_index.get(normalize(canonical)), canonical\n\n\ndef style_workbook(path):\n    """Rendre le classeur de contrôle directement lisible."""\n    wb = load_workbook(path)\n    colors = {\n        "Prête": "D9EAD3",\n        "À compléter": "FFF2CC",\n        "Cas spécial": "CFE2F3",\n        "Exclue": "F4CCCC",\n        "Continuité": "D9D2E9",\n    }\n    for ws in wb.worksheets:\n        ws.freeze_panes = "A2"\n        ws.auto_filter.ref = ws.dimensions\n        for cell in ws[1]:\n            cell.fill = PatternFill("solid", fgColor="1F4E78")\n            cell.font = Font(color="FFFFFF", bold=True)\n            cell.alignment = Alignment(horizontal="center", wrap_text=True)\n        for row in ws.iter_rows(min_row=2):\n            for cell in row:\n                cell.alignment = Alignment(vertical="top", wrap_text=True)\n            if ws.title == "Univers individuel":\n                status = str(row[6].value)\n                for prefix, color in colors.items():\n                    if status.startswith(prefix):\n                        row[6].fill = PatternFill("solid", fgColor=color)\n                        break\n        for column_cells in ws.columns:\n            letter = get_column_letter(column_cells[0].column)\n            width = min(55, max(12, max(len(str(c.value or "")) for c in column_cells) + 2))\n            ws.column_dimensions[letter].width = width\n    wb.save(path)\n\n\ndef main():\n    """Créer le registre final et les listes d\'action."""\n    panel = pd.read_excel(PANEL_FILE, sheet_name="Panel provisoire")\n    forecasts = pd.read_excel(FORECAST_FILE, sheet_name="Previsions IS 2026")\n    panel_names = sorted(panel["societe"].dropna().astype(str).unique())\n    forecast_names = sorted(forecasts["societe"].dropna().astype(str).unique())\n\n    source_univers = "Classeur IS original réparé"\n    try:\n        repair_xlsx(INPUT, REPAIRED)\n        wide = pd.read_excel(REPAIRED, sheet_name=0, header=2)\n        company_col = wide.columns[0]\n        years = [\n            c for c in wide.columns[1:]\n            if pd.notna(pd.to_numeric(c, errors="coerce"))\n        ]\n        initial = wide[wide[company_col].notna()].copy()\n    except (BadZipFile, ValueError, OSError):\n        # Le fichier reçu contient des octets de remplacement UTF-8 dans sa\n        # structure ZIP. Le registre de collecte local devient alors la source\n        # de secours la plus traçable; les noms visibles manquants sont ajoutés.\n        registry = pd.read_excel(COMPANY_REGISTRY)\n        names = registry["Société"].dropna().astype(str).tolist()\n        names.extend(CAPTURE_ADDITIONS)\n        names = list(dict.fromkeys(names))\n        initial = pd.DataFrame({"Société": names})\n        company_col = "Société"\n        years = []\n        source_univers = (\n            "Registre local societes.xlsx + noms visibles sur les captures; "\n            "classeur IS original binaire endommagé"\n        )\n\n    rows = []\n    for _, record in initial.iterrows():\n        original = str(record[company_col]).strip()\n        norm = normalize(original)\n        panel_match, canonical = find_equivalent(original, panel_names)\n        forecast_match, _ = find_equivalent(original, forecast_names)\n        if years:\n            values = pd.to_numeric(record[years], errors="coerce")\n            non_null_years = [\n                int(float(y)) for y, value in zip(years, values) if pd.notna(value)\n            ]\n        elif panel_match:\n            company_panel = panel[panel["societe"].eq(panel_match)]\n            non_null_years = (\n                company_panel.loc[company_panel["is_mad"].notna(), "annee"]\n                .dropna().astype(int).tolist()\n            )\n        else:\n            non_null_years = []\n\n        if norm in CONTINUITES:\n            status = "Continuité avec une société actuelle"\n            reason = CONTINUITES[norm]\n            action = "Contrôler les doublons et conserver un identifiant canonique unique"\n        elif norm in EXCLUSIONS:\n            status = "Exclue de la population active 2026"\n            reason = EXCLUSIONS[norm]\n            action = "Conserver l\'historique, mais ne pas produire de prévision 2026"\n        elif norm in CAS_SPECIAUX:\n            status = "Cas spécial"\n            reason = CAS_SPECIAUX[norm]\n            action = "Traiter séparément après contrôle des comptes récents"\n        elif forecast_match:\n            status = "Prête : prévision 2026 disponible"\n            reason = "Société retrouvée dans le fichier de prévisions"\n            action = "Conserver et contrôler la cohérence finale"\n        else:\n            status = "À compléter / vérifier"\n            reason = (\n                "Présente dans le panel mais sans prévision"\n                if panel_match\n                else "Absente du panel financier sous ce libellé"\n            )\n            action = "Vérifier la cotation 2026, l\'alias puis collecter IS et variables 2025"\n\n        rows.append(\n            {\n                "societe_base_is": original,\n                "societe_canonique": canonical,\n                "correspondance_panel": panel_match or "",\n                "correspondance_prevision": forecast_match or "",\n                "premiere_annee_is_disponible": min(non_null_years) if non_null_years else pd.NA,\n                "derniere_annee_is_disponible": max(non_null_years) if non_null_years else pd.NA,\n                "statut_univers_2026": status,\n                "justification": reason,\n                "action_suivante": action,\n                "source_univers": source_univers,\n            }\n        )\n\n    universe = pd.DataFrame(rows)\n    # Une ligne de total ou une note de bas de page n\'est pas une entreprise.\n    normalized_labels = universe["societe_base_is"].map(normalize)\n    invalid = (\n        normalized_labels.isin(\n            {"total", "total de l is des societes cotees", "non encore cotee a la bourse"}\n        )\n        | normalized_labels.str.contains(r"^\\*+ radiee de la cote$", regex=True)\n    )\n    notes = universe[invalid].copy()\n    universe = universe[~invalid].copy()\n\n    summary = (\n        universe.groupby("statut_univers_2026", dropna=False)\n        .size()\n        .reset_index(name="nombre_lignes_base_is")\n        .sort_values("statut_univers_2026")\n    )\n    metadata = pd.DataFrame(\n        [\n            ["Source utilisée", source_univers],\n            ["Lignes analysées", len(universe)],\n            ["Sociétés dans le panel financier", len(panel_names)],\n            ["Sociétés avec prévision 2026", len(forecast_names)],\n            [\n                "Limite",\n                "Les sociétés classées « À compléter / vérifier » nécessitent "\n                "un contrôle AMMC avant d\'être déclarées actives en 2026.",\n            ],\n        ],\n        columns=["element", "valeur"],\n    )\n    todo = universe[universe["statut_univers_2026"].eq("À compléter / vérifier")].copy()\n    active_ready = universe[\n        universe["statut_univers_2026"].str.startswith("Prête")\n        | universe["statut_univers_2026"].str.startswith("Continuité")\n    ].copy()\n\n    with pd.ExcelWriter(OUTPUT_FILE, engine="openpyxl") as writer:\n        universe.to_excel(writer, sheet_name="Univers individuel", index=False)\n        summary.to_excel(writer, sheet_name="Synthese", index=False)\n        todo.to_excel(writer, sheet_name="A completer", index=False)\n        active_ready.to_excel(writer, sheet_name="Pretes et continuite", index=False)\n        notes.to_excel(writer, sheet_name="Lignes non societes", index=False)\n        metadata.to_excel(writer, sheet_name="Tracabilite", index=False)\n    style_workbook(OUTPUT_FILE)\n\n    print(summary.to_string(index=False))\n    print(f"\\nLignes d\'entreprises analysées : {len(universe)}")\n    print(f"Prévisions actuellement disponibles : {len(forecast_names)}")\n    print(f"À compléter ou vérifier : {len(todo)}")\n    print(f"Créé : {OUTPUT_FILE.resolve()}")\n\n\nif __name__ == "__main__":\n    main()\n',
    '55_auditer_31_societes_restantes.py': '"""Finaliser l\'audit des 31 sociétés restant à vérifier dans l\'univers 2026."""\n\nfrom pathlib import Path\n\nimport pandas as pd\nfrom openpyxl import load_workbook\nfrom openpyxl.styles import Alignment, Font, PatternFill\nfrom openpyxl.utils import get_column_letter\n\n\nOUT = Path("data/output")\nSOURCE = OUT / "univers_final_previsions_is_2026.xlsx"\nOUTPUT = OUT / "audit_31_societes_restantes_2026.xlsx"\n\n# statut, identité actuelle, justification, source\nDECISIONS = {\n    "Centrale laitière": ("Active à compléter", "Centrale Danone", "Action CLT toujours référencée; changement de dénomination", "https://www.ammc.ma/fr/instruments-financiers/actions/action-centrale-laitiere"),\n    "Dari couspate": ("Active à compléter", "Dari Couspate", "Société cotée; IS/variables 2025 à finaliser", "https://www.ammc.ma/fr/espace-emetteurs/liste-des-emetteurs"),\n    "Lafarge Ciments": ("Continuité déjà couverte", "LafargeHolcim Maroc", "Lafarge Ciments a absorbé Holcim Maroc puis changé de dénomination en 2016", "https://www.ammc.ma/sites/default/files/LHM_fusion_039_2016.pdf"),\n    "Lafarg Holcim Maroc": ("Continuité déjà couverte", "LafargeHolcim Maroc", "Libellé alternatif de la société déjà représentée par Holcim dans le panel", "https://www.ammc.ma/fr/espace-emetteurs/liste-des-emetteurs/2784"),\n    "Sonacid": ("Active à compléter", "SONASID", "Société cotée avec résultats financiers 2025 publiés", "https://www.ammc.ma/fr/espace-emetteurs/sonasid"),\n    "Longometal": ("Exclue", "", "Émetteur sans date d\'introduction en actions; absent de l\'univers actions coté actuel", "https://v8.ammc.ma/fr/espace-emetteurs/liste-des-emetteurs?field_compartiment_value=All&field_cote_bourse_value=All&field_secteur_activite_value=All&page=7&title="),\n    "ENNAKL (en Dinar Tunisien)": ("Active à compléter", "ENNAKL AUTOMOBILES", "Société cotée et publications financières 2025/2026 disponibles", "https://www.ammc.ma/fr/espace-emetteurs/liste-des-emetteurs/2772"),\n    "SRM": ("Active à compléter", "SRM SA", "Société toujours cotée; rapport annuel 2025 exact à collecter", "https://www.ammc.ma/fr/espace-emetteurs/liste-des-emetteurs?page=11"),\n    "Distrisoft Maroc": ("Continuité déjà couverte", "Disway", "Absorbée par Matel PC Market, devenue Disway en 2010", "https://www.ammc.ma/sites/default/files/NI_BT_Disway.pdf"),\n    "Involys": ("Active à compléter", "INVOLYS", "Société cotée; rapport financier annuel 2025 publié", "https://www.ammc.ma/fr/espace-emetteurs/liste-des-emetteurs/2781"),\n    "IB Maroc.com": ("Active à compléter", "IB MAROC.COM", "Société cotée, à compléter avec ses comptes 2025", "https://www.ammc.ma/fr/espace-emetteurs/liste-des-emetteurs?page=6"),\n    "CARNAUD": ("Exclue", "", "Ancienne valeur non retrouvée dans l\'univers actuel des actions cotées", "https://www.ammc.ma/fr/espace-emetteurs/liste-des-emetteurs"),\n    "GENERAL TIRE": ("Exclue", "", "Ancien émetteur; page AMMC sans date ni compartiment d\'action actuel", "https://www.ammc.ma/fr/espace-emetteurs/general-tire"),\n    "Le Carton": ("Exclue", "", "Statut AMMC : Radié de la bourse; OPR visée en 2008", "https://www.ammc.ma/fr/espace-emetteurs/le-carton"),\n    "PROMOPHARM": ("Active à compléter", "PROMOPHARM", "Société cotée; rapport financier annuel 2025 publié", "https://www.ammc.ma/fr/espace-emetteurs/liste-des-emetteurs/2812"),\n    "BCP": ("Active à compléter", "Banque Centrale Populaire", "Action cotée depuis 2004", "https://www.ammc.ma/fr/espace-emetteurs/liste-des-emetteurs?page=1"),\n    "BNDE": ("Exclue", "", "Statut AMMC : Radié de la bourse", "https://www.ammc.ma/fr/espace-emetteurs/liste-des-emetteurs/2744"),\n    "CAM": ("Exclue de l\'univers actions", "Crédit Agricole du Maroc", "Émetteur présent sans date d\'introduction en actions", "https://www.ammc.ma/en/espace-emetteurs/liste-des-emetteurs?field_compartiment_value=All&field_cote_bourse_value=All&field_secteur_activite_value=All&page=4&title="),\n    "Acred": ("Exclue", "AXA Crédit", "AXA Crédit, ex-Acred, a été radiée", "https://www.ammc.ma/sites/default/files/DR_Wafasalaf_008_2025.pdf"),\n    "CREDOR": ("Exclue / absorbée", "Wafasalaf", "OPR puis fusion avec Wafasalaf en 2004", "https://www.ammc.ma/fr/actualites/communique-presse/offre-publique-de-retrait-sur-les-actions-de-la-societe-credor"),\n    "Diac équipement": ("Exclue de l\'univers actions", "", "Page AMMC sans date d\'introduction ni compartiment d\'action actuel", "https://www.ammc.ma/fr/espace-emetteurs/liste-des-emetteurs/2768"),\n    "Taslif": ("Continuité déjà couverte", "SALAFIN", "Fusion-absorption de Taslif par Salafin le 31/12/2018", "https://www.ammc.ma/sites/default/files/DR_Wafasalaf_008_2025.pdf"),\n    "Maroc Leasing": ("Active à compléter", "MAROC LEASING SA", "Société cotée; IS 2025 déjà identifié dans le rapport social", "https://www.ammc.ma/fr/espace-emetteurs/liste-des-emetteurs?page=7"),\n    "AFMA": ("Active à compléter", "AFMA", "Société cotée depuis 2015", "https://www.ammc.ma/fr/espace-emetteurs/liste-des-emetteurs"),\n    "JALU (JET CONTRACTORS)": ("Active à compléter", "JET CONTRACTORS", "Société cotée depuis 2011", "https://www.ammc.ma/fr/espace-emetteurs/liste-des-emetteurs?page=6"),\n    "S2M": ("Active à compléter", "S2M", "Société cotée depuis 2011", "https://www.ammc.ma/fr/espace-emetteurs/liste-des-emetteurs?page=9"),\n    "TAQA MOROCCO": ("Active à compléter", "TAQA MOROCCO", "Société cotée depuis 2013", "https://www.ammc.ma/fr/espace-emetteurs/liste-des-emetteurs?page=11"),\n    "ARADEI Capital": ("Active à compléter", "ARADEI CAPITAL", "Société cotée depuis 2020", "https://www.ammc.ma/fr/espace-emetteurs/liste-des-emetteurs?page=1"),\n    "AKDITAL": ("Active à compléter", "AKDITAL", "Société cotée depuis 2022", "https://www.ammc.ma/fr/espace-emetteurs/liste-des-emetteurs"),\n    "CREDIT AGRICOLE DU MAROC": ("Exclue de l\'univers actions", "Crédit Agricole du Maroc", "Doublon de CAM; émetteur sans action cotée", "https://www.ammc.ma/en/espace-emetteurs/liste-des-emetteurs?field_compartiment_value=All&field_cote_bourse_value=All&field_secteur_activite_value=All&page=4&title="),\n    "TOTAL MAROC": ("Active à compléter", "TotalEnergies Marketing Maroc", "Société cotée; changement de dénomination", "https://www.ammc.ma/fr/espace-emetteurs/liste-des-emetteurs"),\n}\n\n\ndef main():\n    todo = pd.read_excel(SOURCE, sheet_name="A completer")\n    rows = []\n    for company in todo["societe_base_is"]:\n        decision = DECISIONS.get(company)\n        if decision is None:\n            raise ValueError(f"Décision manquante pour {company}")\n        status, current_name, reason, source = decision\n        rows.append({\n            "societe_base_is": company,\n            "identite_actuelle": current_name,\n            "statut_final": status,\n            "justification": reason,\n            "action": (\n                "Collecter/valider IS et variables financières 2025"\n                if status == "Active à compléter"\n                else "Ne pas créer une nouvelle prévision indépendante"\n                if status == "Continuité déjà couverte"\n                else "Conserver seulement l\'historique"\n            ),\n            "source": source,\n        })\n    audit = pd.DataFrame(rows)\n    summary = audit.groupby("statut_final").size().reset_index(name="nombre")\n    priority = audit[audit["statut_final"].eq("Active à compléter")].copy()\n\n    with pd.ExcelWriter(OUTPUT, engine="openpyxl") as writer:\n        audit.to_excel(writer, sheet_name="Audit final 31", index=False)\n        summary.to_excel(writer, sheet_name="Synthese", index=False)\n        priority.to_excel(writer, sheet_name="Collecte prioritaire 2025", index=False)\n\n    wb = load_workbook(OUTPUT)\n    colors = {\n        "Active": "D9EAD3",\n        "Continuité": "D9D2E9",\n        "Exclue": "F4CCCC",\n    }\n    for ws in wb.worksheets:\n        ws.freeze_panes = "A2"\n        ws.auto_filter.ref = ws.dimensions\n        for cell in ws[1]:\n            cell.fill = PatternFill("solid", fgColor="1F4E78")\n            cell.font = Font(color="FFFFFF", bold=True)\n        for row in ws.iter_rows(min_row=2):\n            for cell in row:\n                cell.alignment = Alignment(vertical="top", wrap_text=True)\n            if ws.title == "Audit final 31":\n                for prefix, color in colors.items():\n                    if str(row[2].value).startswith(prefix):\n                        row[2].fill = PatternFill("solid", fgColor=color)\n        for cells in ws.columns:\n            letter = get_column_letter(cells[0].column)\n            ws.column_dimensions[letter].width = min(\n                70, max(12, max(len(str(c.value or "")) for c in cells) + 2)\n            )\n    wb.save(OUTPUT)\n    print(summary.to_string(index=False))\n    print(f"\\nSociétés actives à compléter : {len(priority)}")\n    print(priority[["societe_base_is", "identite_actuelle"]].to_string(index=False))\n    print(f"\\nCréé : {OUTPUT.resolve()}")\n\n\nif __name__ == "__main__":\n    main()\n',
}


def list_scripts() -> None:
    """Affiche les étapes historiques disponibles dans ce regroupement."""
    for script_name in sorted(SCRIPTS):
        print(script_name)


def run_script(script_name: str) -> None:
    """Exécute un script historique dans un espace de noms isolé."""
    normalized = script_name if script_name.endswith(".py") else f"{script_name}.py"
    if normalized not in SCRIPTS:
        choices = ", ".join(sorted(SCRIPTS))
        raise SystemExit(f"Script inconnu : {script_name}\nChoix disponibles : {choices}")

    previous_directory = Path.cwd()
    os.chdir(PROJECT_ROOT)
    namespace = {
        "__name__": "__main__",
        "__file__": str(PROJECT_ROOT / normalized),
        "__package__": None,
    }
    try:
        source = SCRIPTS[normalized]
        exec(compile(source, namespace["__file__"], "exec"), namespace)
    finally:
        os.chdir(previous_directory)


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Lister ou exécuter une étape historique regroupée."
    )
    parser.add_argument("script", nargs="?", help="Nom du script à exécuter.")
    parser.add_argument(
        "--list", action="store_true", help="Afficher les scripts disponibles."
    )
    args = parser.parse_args()

    if args.list or not args.script:
        list_scripts()
        return
    run_script(args.script)


if __name__ == "__main__":
    main()
